/** Shows touch or keyboard controls and help text. Safe to call again when the player changes device in Settings. */
function applyPlayMode(mode:PlayMode){
  mobileMode = mode === 'mobile';
  document.documentElement.dataset.playMode = mode;
  const help = mobileMode ? touchHelp : webHelp;
  document.querySelector('#help')!.textContent = help;
  const briefing = document.querySelector('.ready-keys');
  if (briefing) briefing.textContent = help;
  document.querySelectorAll<HTMLElement>('.field-manual [data-manual]').forEach(row => { row.hidden = row.dataset.manual === 'web' ? mobileMode : !mobileMode; });
}
/** Loads the named driver's save and closes the welcome screen. Returns false when the name is empty. */
function enterGame(name:string,difficulty?:'easy'|'normal'|'hard'){
  driver=name.trim().normalize('NFC');
  document.querySelector('#driverLabel')!.textContent=driver||tr('车手','Driver');
  if(!driver){nameField.value='';nameField.reportValidity();return false;}
  try{loadDriver(driver);variants=JSON.parse(localStorage.getItem('arena-variants:'+driver)??'[0,0,0,0,0]');record=Number(localStorage.getItem('arena-best:'+driver))||0;}catch{}
  if(difficulty){profileStore.data.settings.difficulty=difficulty;profileStore.save();}
  selectedCar=profileStore.data.car;selectedMode=profileStore.data.mode;selectedArena=profileStore.data.arena;inputMode=profileStore.data.settings.control;
  document.querySelector('#record')!.textContent=tr('个人最高积分 ','Personal best ')+record;
  document.querySelectorAll<HTMLSelectElement>('[data-variant]').forEach(el=>el.value=String(variants[Number(el.dataset.variant)]??0));
  applyPlayMode(resolvePlayMode(playChoice));
  renderUI();applySettings();
  if(picker.open)picker.close();
  return true;
}
picker.addEventListener('click', async event => {
  const button = (event.target as HTMLElement).closest('button');
  if (!button) return;
  event.stopPropagation();
  if (button.dataset.lang) { if (saveLang(button.dataset.lang as Lang)) reloadForLanguage({driver:nameField.value,diff:welcomeDifficulty,welcome:true}); return; }
  if (button.dataset.diff) { menuSound('pick',['easy','normal','hard'].indexOf(button.dataset.diff)); welcomeDifficulty = button.dataset.diff as 'easy'|'normal'|'hard'; markWelcome(); return; }
  if (button.dataset.play) { menuSound('pick',button.dataset.play==='mobile'?3:4); welcomePlay = button.dataset.play as PlayMode; markWelcome(); return; }
  if (button.value !== 'start') return;
  // Keep "auto" while the player accepts the detected device, so a different screen is detected afresh next time.
  playChoice = welcomePlay === detectedPlay && playChoice === 'auto' ? 'auto' : welcomePlay;
  savePlayChoice(playChoice);
  if (!enterGame(nameField.value, welcomeDifficulty)) return;
  if (!mobileMode) return;
  try { await document.documentElement.requestFullscreen?.(); } catch {}
  const orientation = screen.orientation as ScreenOrientation & {lock?: (mode:string)=>Promise<void>};
  try { await orientation?.lock?.('landscape'); } catch {}
});
