const palettes=paintColors;document.querySelectorAll<HTMLButtonElement>('[data-skin]').forEach((b,i)=>b.addEventListener('click',()=>{if(!profileStore.paint(i)){menuSound('deny');menuToast(tr('零件不足，完成战斗可以获取','Not enough parts. Win battles to earn more.'));return;}(player.mesh.userData.paint as THREE.MeshStandardMaterial).color.setHex(palettes[i]);player.mesh.userData.basePaint=palettes[i];menuSound('paint',i);renderUI();fx.burst(b);fx.flash();}));
