const sound=new GameAudio();let muted=false;document.querySelector('#mute')!.addEventListener('click',()=>{muted=!muted;sound.setMuted(muted);document.querySelector('#mute')!.textContent=muted?tr('音效 关','Sound off'):tr('音效 开','Sound on');document.querySelector('#mute')?.classList?.toggle('muted',muted);});
/** Menu feedback. The first tap also creates the audio context, which browsers only allow inside a gesture. */
function menuSound(kind:MenuSound,index=0,variant=0){if(running)return;sound.start();sound.setVolume(profileStore.data.settings.volume);sound.menu(kind,index,variant);}
function beep(freq:number,dur:number){sound.setVolume(profileStore.data.settings.volume);sound.blip(freq,dur);}
function gunSound(weapon:number,position:THREE.Vector3,own=false){sound.gun(weapon,position.x,position.z,own);}
