// Objective game modes: flags and charge have distinct win conditions, not kill counters.
const flagHomes=[{x:-16,z:32},{x:16,z:-32}];
const flags=flagHomes.map((home,team)=>{const mesh=new THREE.Group();const pole=box(.09,2.8,.09,mat(0xb7c2b7),0,1.4,0);const cloth=box(1.1,.7,.07,new THREE.MeshBasicMaterial({color:team===0?0x47cfe9:0xf27e61}),.55,2.25,0);mesh.add(pole,cloth);scene.add(mesh);return {team,home,mesh,x:home.x,z:home.z,carrier:null as Car|null,dropped:0};});
