function resetObjectives(){for(const flag of flags){flag.x=flag.home.x;flag.z=flag.home.z;flag.carrier=null;flag.dropped=0;flag.mesh.visible=match.mode==='ctf';flag.mesh.position.set(flag.x,terrainHeight(flag.x,flag.z),flag.z);}chargeCarrier=null;chargeX=mapLayout().charge.x;chargeZ=mapLayout().charge.z;chargeDrop=0;chargeMesh.visible=match.mode==='charge';}
function updateObjectives(dt:number){
 if(match.mode==='ctf')for(const flag of flags){if(flag.carrier&&!flag.carrier.alive){flag.x=flag.carrier.mesh.position.x;flag.z=flag.carrier.mesh.position.z;flag.carrier=null;flag.dropped=12;}if(flag.carrier){const carrier=flag.carrier,home=flags[carrier.team];flag.x=carrier.mesh.position.x;flag.z=carrier.mesh.position.z;if(Math.hypot(flag.x-home.home.x,flag.z-home.home.z)<4&&!home.carrier&&home.dropped===0){match.scores[carrier.team]++;toast(carrier.team===0?tr('蓝队夺旗成功！','Blue captures the flag!'):tr('红队夺旗成功！','Red captures the flag!'),2);flag.carrier=null;flag.x=flag.home.x;flag.z=flag.home.z;flag.dropped=0;if(match.scores[carrier.team]>=3)match.finish(carrier.team);}}else{if(flag.dropped>0){flag.dropped=Math.max(0,flag.dropped-dt);if(flag.dropped===0){flag.x=flag.home.x;flag.z=flag.home.z;}}for(const c of cars){if(!c.alive||Math.hypot(c.mesh.position.x-flag.x,c.mesh.position.z-flag.z)>2.3)continue;if(c.team===flag.team){if(flag.dropped>0){flag.dropped=0;flag.x=flag.home.x;flag.z=flag.home.z;}}else{flag.carrier=c;flag.dropped=0;if(c.player)toast(tr('已夺取敌旗 · 驶回蓝方基地','Flag taken · Drive back to blue base'),2);break;}}}flag.mesh.position.set(flag.x,terrainHeight(flag.x,flag.z)+(flag.carrier?1.5:0),flag.z);}
 if(match.mode==='charge'){if(chargeCarrier&&!chargeCarrier.alive){chargeX=chargeCarrier.mesh.position.x;chargeZ=chargeCarrier.mesh.position.z;chargeCarrier=null;chargeDrop=12;}if(chargeCarrier){chargeX=chargeCarrier.mesh.position.x;chargeZ=chargeCarrier.mesh.position.z;match.scores[chargeCarrier.team]+=dt;if(match.scores[chargeCarrier.team]>=60)match.finish(chargeCarrier.team);}else{if(chargeDrop>0){chargeDrop=Math.max(0,chargeDrop-dt);if(chargeDrop===0){chargeX=mapLayout().charge.x;chargeZ=mapLayout().charge.z;}}const collector=cars.find(c=>c.alive&&Math.hypot(c.mesh.position.x-chargeX,c.mesh.position.z-chargeZ)<2.3);if(collector){chargeCarrier=collector;chargeDrop=0;if(collector.player)toast(tr('获得能量核心 · 躲避敌方追击','You have the core · Shake off pursuers'),2);}}chargeMesh.position.set(chargeX,terrainHeight(chargeX,chargeZ)+(chargeCarrier?3:1.4),chargeZ);chargeMesh.rotation.y+=dt;}
}

