app.addEventListener('click',event=>{const button=(event.target as HTMLElement).closest<HTMLElement>('button');if(!button||running)return;if(button.dataset.lang){if(saveLang(button.dataset.lang as Lang))reloadForLanguage({driver,page:activePage});return;}if(button.dataset.play){menuSound('pick');playChoice=button.dataset.play as PlayChoice;savePlayChoice(playChoice);applyPlayMode(resolvePlayMode(playChoice));renderUI();return;}if(button.id==='nextStep'){menuSound('next');showPage(activePage==='garage'?'armory':activePage==='armory'?'battle':activePage==='battle'?'arena':activePage==='result'?'battle':'garage');return;}if(button.id==='prevStep'){menuSound('back');showPage(activePage==='arena'?'battle':activePage==='battle'?'armory':'garage');return;}if(button.id==='rerollTerrain'){menuSound('reroll');rollTerrain(true);fx.pop(button);return;}if(button.dataset.cycle){selectCar((selectedCar+Number(button.dataset.cycle)+vehicles.length)%vehicles.length);return;}if(button.dataset.tab){tuneTab=button.dataset.tab;menuSound('tab',['weapon','upgrade','paint'].indexOf(tuneTab));renderUI();return;}if(button.dataset.value&&button.parentElement?.dataset.choice){const key=button.parentElement.dataset.choice as 'quality'|'difficulty';(profileStore.data.settings as Record<string,unknown>)[key]=button.dataset.value;menuSound('pick',Array.from(button.parentElement.children).indexOf(button));profileStore.save();renderUI();return;}if(button.dataset.variantPick!==undefined){fx.pop(button);variants[selectedCar]=Number(button.dataset.variantPick);menuSound('weapon',vehicles[selectedCar].weapon,variants[selectedCar]);try{localStorage.setItem('arena-variants:'+driver,JSON.stringify(variants));}catch{}renderUI();return;}if(button.dataset.nav){menuSound(button.dataset.nav===activePage?'back':'next');showPage(button.dataset.nav);}else if(button.dataset.upgrade){const kind=button.dataset.upgrade;if(profileStore.upgrade(selectedCar,kind as Upgrade)){menuSound('upgrade',['armor','engine','weapon'].indexOf(kind));renderUI();const card=document.querySelector<HTMLElement>(`.upgrade-card[data-kind="${kind}"]`);fx.burst(card);fx.float(card,[tr('装甲 +8%','Armour +8%'),tr('极速 +3%','Speed +3%'),tr('伤害 +8%','Damage +8%')][['armor','engine','weapon'].indexOf(kind)]);card?.querySelector('.pips i.on:last-of-type')?.classList?.add('fresh');fx.coins();}else{menuSound('deny');menuToast(tr('升级未完成：零件不足或已达上限','Upgrade failed: not enough parts, or already maxed'));renderUI();}}else if(button.dataset.weapon!==undefined){selectedCar=Number(button.dataset.weapon);profileStore.data.car=selectedCar;profileStore.data.weapon=vehicles[selectedCar].weapon;profileStore.save();renderUI();}else if(button.dataset.arena!==undefined){selectedArena=Number(button.dataset.arena);menuSound('arena',selectedArena);fx.pop(button);profileStore.data.arena=selectedArena;profileStore.save();renderUI();}else if(button.dataset.claim){const card=button.closest<HTMLElement>('.milestone');if(profileStore.claim(button.dataset.claim)){menuSound('claim');fx.burst(card);fx.coins();menuToast(tr('里程碑奖励已领取','Milestone reward claimed'));}renderUI();}});
