if(typeof window!=='undefined'){syncViewport();window.visualViewport?.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('scroll',syncViewport);addEventListener('orientationchange',()=>{syncViewport();setTimeout(syncViewport,120);setTimeout(syncViewport,350);});addEventListener('pageshow',syncViewport);assetPromise=loadAssetLibrary((done,total)=>{assetProgress=`${tr('三维资源','3D assets')} ${done}/${total}`;document.querySelector('#assetStatus')!.textContent=assetProgress;}).then(ready=>{modelsReady=ready;if(ready)applyLoadedAssets();else document.querySelector('#assetStatus')!.textContent=tr('模型未完整加载 · 请刷新重试','Models did not fully load · Refresh to retry');return ready;});}

const visionLines=[0x6fc5b6,0xc6a16b].map(color=>{const line=new THREE.LineLoop(new THREE.BufferGeometry().setAttribute('position',new THREE.BufferAttribute(new Float32Array(96*3),3)),new THREE.LineBasicMaterial({color,transparent:true,opacity:.14}));scene.add(line);return line;});
function updateVisionLines(){const viewer=player.alive?player:cars.find(c=>c.alive&&c.team===player.team)??player;visionLines.forEach((line,index)=>{line.visible=running;const radius=index===0?vehicles[viewer.loadout].vision:weapons[viewer.weapon].range,points=line.geometry.attributes.position;for(let j=0;j<96;j++){const a=j/96*Math.PI*2,vx=viewer.mesh.position.x,vz=viewer.mesh.position.z,r=index===0?sightRange(radius,viewer.mesh.position.y,terrainHeight(vx+Math.cos(a)*radius,vz+Math.sin(a)*radius)):radius,x=vx+Math.cos(a)*r,z=vz+Math.sin(a)*r;points.setXYZ(j,x,terrainHeight(x,z)+.12,z);}points.needsUpdate=true;line.geometry.computeBoundingSphere();});}

document.querySelectorAll<HTMLSelectElement>('[data-variant]').forEach(select=>{
 const i=Number(select.dataset.variant);
 select.addEventListener('change',()=>{
  variants[i]=Number(select.value);
  try{localStorage.setItem('arena-variants:'+driver,JSON.stringify(variants));}catch{}
  renderUI();
 });
});
const issuesURL='https://github.com/ZixunHuangUPenn/Arena-Wreckers/issues/new';
document.querySelector('#publishWins')!.addEventListener('click',()=>{
 const params=new URLSearchParams({title:'Arena Wreckers · 胜场记录',body:JSON.stringify({driver,wins:profileStore.data.wins})});
 window.open(issuesURL+'?'+params,'_blank','noopener');
});
document.querySelector('#readWins')!.addEventListener('click',async()=>{
 const list=document.querySelector('#winsList')!;
 list.textContent=tr('正在读取…','Loading…');
 try{
  const best=new Map<string,{name:string;wins:number}>();
  for(let page=1;;page++){
   const response=await fetch('https://api.github.com/repos/ZixunHuangUPenn/Arena-Wreckers/issues?state=all&per_page=100&page='+page);
   if(!response.ok)throw Error();
   const issues=await response.json();
   for(const issue of issues){
    if(issue.pull_request||issue.title!=='Arena Wreckers · 胜场记录')continue;
    try{const {driver:name,wins}=JSON.parse(issue.body);
     if(typeof name==='string'&&name.trim()&&Number.isSafeInteger(wins)&&wins>=0&&wins>(best.get(issue.user.login)?.wins??-1))best.set(issue.user.login,{name:name.slice(0,24),wins});
    }catch{}
   }
   if(issues.length<100)break;
  }
  list.textContent=[...best.entries()].sort((a,b)=>b[1].wins-a[1].wins).map(([login,p],i)=>(i+1)+'. '+p.name+' (@'+login+') · '+p.wins+tr(' 胜',' wins')).join('\n')||tr('还没有公开记录','No public records yet');
 }catch{list.textContent=tr('排行榜暂时无法读取，请稍后重试','The leaderboard could not be read. Try again later.');}
});
